CREATE TABLE app_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE devices(id TEXT PRIMARY KEY,name TEXT NOT NULL,platform TEXT NOT NULL,kind TEXT NOT NULL,host_device_id TEXT NOT NULL,public_key TEXT,capabilities TEXT NOT NULL DEFAULT '[]',last_address TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,last_seen_at INTEGER NOT NULL);
CREATE TABLE browser_sessions(token_hash TEXT PRIMARY KEY,device_id TEXT NOT NULL REFERENCES devices(id),expires_at INTEGER NOT NULL,last_seen_at INTEGER NOT NULL);
CREATE TABLE groups(id TEXT PRIMARY KEY,name TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES devices(id),revision INTEGER NOT NULL CHECK(revision>=1),snapshot_json TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE group_members(group_id TEXT NOT NULL REFERENCES groups(id),device_id TEXT NOT NULL REFERENCES devices(id),invite_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('owner','member')),state TEXT NOT NULL CHECK(state IN ('invited','joined','left')),sequence INTEGER NOT NULL,event_json TEXT,invited_at INTEGER NOT NULL,joined_at INTEGER,left_at INTEGER,PRIMARY KEY(group_id,device_id));
CREATE TABLE conversations(id TEXT PRIMARY KEY,principal_id TEXT NOT NULL REFERENCES devices(id),kind TEXT NOT NULL CHECK(kind IN ('direct','group')),peer_id TEXT REFERENCES devices(id),group_id TEXT REFERENCES groups(id),last_message_at INTEGER NOT NULL DEFAULT 0,last_read_at INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,CHECK((kind='direct' AND peer_id IS NOT NULL AND group_id IS NULL) OR (kind='group' AND peer_id IS NULL AND group_id IS NOT NULL)),UNIQUE(principal_id,peer_id),UNIQUE(principal_id,group_id));
CREATE TABLE messages(id TEXT PRIMARY KEY,sender_id TEXT NOT NULL REFERENCES devices(id),sender_name TEXT NOT NULL,group_id TEXT REFERENCES groups(id),text TEXT NOT NULL,created_at INTEGER NOT NULL,received_at INTEGER NOT NULL);
CREATE TABLE conversation_messages(position INTEGER PRIMARY KEY AUTOINCREMENT,conversation_id TEXT NOT NULL REFERENCES conversations(id),message_id TEXT NOT NULL REFERENCES messages(id),direction TEXT NOT NULL CHECK(direction IN ('incoming','outgoing')),read_at INTEGER,UNIQUE(conversation_id,message_id));
CREATE TABLE attachments(message_id TEXT NOT NULL REFERENCES messages(id),file_id TEXT NOT NULL,name TEXT NOT NULL,size INTEGER NOT NULL CHECK(size>=0),mime TEXT NOT NULL,position INTEGER NOT NULL,PRIMARY KEY(message_id,file_id));
CREATE TABLE deliveries(id TEXT PRIMARY KEY,message_id TEXT NOT NULL REFERENCES messages(id),recipient_id TEXT NOT NULL REFERENCES devices(id),recipient_name TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','accepted','transferring','completed','rejected','cancelled','failed','interrupted')),bytes INTEGER NOT NULL,total INTEGER NOT NULL,error TEXT,incoming_remote INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(message_id,recipient_id));
CREATE TABLE file_blobs(id TEXT PRIMARY KEY,relative_path TEXT NOT NULL UNIQUE,size INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('available','missing','expired')),created_at INTEGER NOT NULL);
CREATE TABLE delivery_files(delivery_id TEXT NOT NULL REFERENCES deliveries(id),file_id TEXT NOT NULL,blob_id TEXT NOT NULL REFERENCES file_blobs(id),complete INTEGER NOT NULL,PRIMARY KEY(delivery_id,file_id));
CREATE TABLE conversation_drafts(conversation_id TEXT PRIMARY KEY REFERENCES conversations(id),text TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX timeline_page ON conversation_messages(conversation_id,position DESC);
CREATE INDEX conversation_recent ON conversations(principal_id,last_message_at DESC);
CREATE INDEX delivery_status ON deliveries(status);
CREATE INDEX member_device ON group_members(device_id,state);
CREATE INDEX message_attachments ON attachments(message_id,position);
CREATE INDEX blob_references ON delivery_files(blob_id);
CREATE INDEX session_expiry ON browser_sessions(expires_at);
